-- The goal's owner remains an active internal human, including across native account doors.
CREATE TRIGGER peg_goal_valid_owner_insert BEFORE INSERT ON peg_goals
WHEN NOT EXISTS (SELECT 1 FROM oa_operators o LEFT JOIN peg_workspace_members m ON m.operator_id=o.id AND m.workspace_id=NEW.workspace_id WHERE o.id=NEW.owner_id AND o.status='active' AND (o.role IN ('owner','admin') OR m.role IN ('manager','member') OR NEW.scope='personal' AND m.role='analyst'))
BEGIN SELECT RAISE(ABORT,'goal_owner_transfer_required'); END;
CREATE TRIGGER peg_goal_valid_owner_update BEFORE UPDATE OF owner_id,scope ON peg_goals
WHEN NOT EXISTS (SELECT 1 FROM oa_operators o LEFT JOIN peg_workspace_members m ON m.operator_id=o.id AND m.workspace_id=NEW.workspace_id WHERE o.id=NEW.owner_id AND o.status='active' AND (o.role IN ('owner','admin') OR m.role IN ('manager','member') OR NEW.scope='personal' AND m.role='analyst'))
BEGIN SELECT RAISE(ABORT,'goal_owner_transfer_required'); END;
CREATE TRIGGER peg_goal_operator_owner_guard BEFORE UPDATE OF status,role ON oa_operators
WHEN EXISTS (SELECT 1 FROM peg_goals g LEFT JOIN peg_workspace_members m ON m.operator_id=NEW.id AND m.workspace_id=g.workspace_id WHERE g.owner_id=NEW.id AND (NEW.status<>'active' OR NOT(NEW.role IN ('owner','admin') OR COALESCE(m.role,'') IN ('manager','member') OR g.scope='personal' AND COALESCE(m.role,'')='analyst')))
BEGIN SELECT RAISE(ABORT,'goal_owner_transfer_required'); END;
CREATE TRIGGER peg_goal_member_owner_guard BEFORE UPDATE OF role ON peg_workspace_members
WHEN EXISTS (SELECT 1 FROM peg_goals g JOIN oa_operators o ON o.id=NEW.operator_id WHERE g.owner_id=NEW.operator_id AND g.workspace_id=NEW.workspace_id AND o.role NOT IN ('owner','admin') AND NOT(NEW.role IN ('manager','member') OR g.scope='personal' AND NEW.role='analyst'))
BEGIN SELECT RAISE(ABORT,'goal_owner_transfer_required'); END;
CREATE TRIGGER peg_goal_member_owner_delete BEFORE DELETE ON peg_workspace_members
WHEN EXISTS (SELECT 1 FROM peg_goals g JOIN oa_operators o ON o.id=OLD.operator_id WHERE g.owner_id=OLD.operator_id AND g.workspace_id=OLD.workspace_id AND o.role NOT IN ('owner','admin'))
BEGIN SELECT RAISE(ABORT,'goal_owner_transfer_required'); END;

CREATE TABLE peg_goal_sources (id TEXT PRIMARY KEY, goal_id TEXT NOT NULL, owner_id TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('csv','api')), token_hash TEXT, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER);
ALTER TABLE peg_goal_events ADD COLUMN source_id TEXT;
CREATE TRIGGER peg_goal_source_insert AFTER INSERT ON peg_goal_sources BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;
CREATE TRIGGER peg_goal_source_update AFTER UPDATE ON peg_goal_sources BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;

CREATE TABLE peg_approval_reopen_guards (task_id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, cause TEXT NOT NULL, at INTEGER NOT NULL);
CREATE TRIGGER peg_approval_reopen_attribution BEFORE UPDATE OF status ON peg_tasks
WHEN OLD.status='done' AND NEW.status<>'done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=OLD.id) AND NOT EXISTS(SELECT 1 FROM peg_decision_guards WHERE task_id=OLD.id) AND NOT EXISTS(SELECT 1 FROM peg_approval_reopen_guards WHERE task_id=OLD.id)
BEGIN SELECT RAISE(ABORT,'attributed_reopen_required'); END;
CREATE TRIGGER peg_approval_reopened_history AFTER UPDATE OF status ON peg_tasks
WHEN OLD.status='done' AND NEW.status<>'done' AND EXISTS(SELECT 1 FROM peg_approval_tasks WHERE task_id=OLD.id) AND NOT EXISTS(SELECT 1 FROM peg_decision_guards WHERE task_id=OLD.id)
BEGIN
 INSERT INTO peg_history(task_id,project_id,at,actor_id,kind,detail) SELECT task_id,NULL,at,actor_id,'decision.reopened',json_object('cause',cause) FROM peg_approval_reopen_guards WHERE task_id=OLD.id;
 DELETE FROM peg_approval_reopen_guards WHERE task_id=OLD.id;
END;

-- A numeric source ends for good: revocation, expiry or a change of accountable owner. Ownership loss is enforced where
-- the owner changes, whichever door changes it, and an ended source never resumes.
ALTER TABLE peg_goal_sources ADD COLUMN ended_at INTEGER;
ALTER TABLE peg_goal_sources ADD COLUMN ended_cause TEXT CHECK(ended_cause IN ('revoked','ownership_changed'));
UPDATE peg_goal_sources SET ended_at=revoked_at,ended_cause='revoked' WHERE revoked_at IS NOT NULL;
UPDATE peg_goal_sources SET ended_at=CAST(strftime('%s','now') AS INTEGER)*1000,ended_cause='ownership_changed' WHERE ended_at IS NULL AND owner_id<>(SELECT owner_id FROM peg_goals WHERE id=peg_goal_sources.goal_id);
ALTER TABLE peg_goal_sources DROP COLUMN revoked_at;
CREATE TRIGGER peg_goal_owner_ends_sources AFTER UPDATE OF owner_id ON peg_goals WHEN OLD.owner_id<>NEW.owner_id
BEGIN UPDATE peg_goal_sources SET ended_at=CAST(strftime('%s','now') AS INTEGER)*1000,ended_cause='ownership_changed' WHERE goal_id=NEW.id AND ended_at IS NULL; END;

-- An observation's identity is (goal, source, key): a person's key can never collide with, replay or poison a source's.
-- Source events carry the source as their recorder, never the person who authorized it.
CREATE TABLE peg_goal_events_next (goal_id TEXT NOT NULL,source_id TEXT NOT NULL DEFAULT '',event_key TEXT NOT NULL,value REAL NOT NULL,observed_at INTEGER NOT NULL,received_at INTEGER NOT NULL,actor_id TEXT NOT NULL,PRIMARY KEY(goal_id,source_id,event_key));
INSERT INTO peg_goal_events_next SELECT goal_id,COALESCE(source_id,''),CASE WHEN source_id IS NOT NULL AND substr(event_key,1,length(source_id)+1)=source_id||':' THEN substr(event_key,length(source_id)+2) ELSE event_key END,value,observed_at,received_at,COALESCE(source_id,actor_id) FROM peg_goal_events;
DROP TABLE peg_goal_events;
ALTER TABLE peg_goal_events_next RENAME TO peg_goal_events;
CREATE TRIGGER peg_goal_event_immutable BEFORE UPDATE ON peg_goal_events BEGIN SELECT RAISE(ABORT,'immutable_numeric_event'); END;
CREATE TRIGGER peg_goal_event_revision AFTER INSERT ON peg_goal_events BEGIN UPDATE peg_personal_revision SET value=value+1 WHERE id=1; END;

-- Reviewed time delivery: one durable row per approved entry and receiver account. A row is claimed (sending) before
-- its provider request, so a lost response stays visible as uncertain and is read back before anything is resent.
CREATE TABLE peg_time_deliveries (
 service TEXT NOT NULL CHECK(service IN ('harvest','quickbooks-time')),account TEXT NOT NULL,entry_id TEXT NOT NULL,sheet_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('entry','correction')),target_entry_id TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('sending','uncertain','acknowledged','rejected')),provider_id INTEGER,
 seconds INTEGER NOT NULL,provider_seconds REAL,request TEXT NOT NULL,status_code INTEGER,reason TEXT,
 attempts INTEGER NOT NULL DEFAULT 1,actor_id TEXT NOT NULL,updated_at INTEGER NOT NULL,
 PRIMARY KEY(service,account,entry_id)
);
CREATE INDEX peg_time_delivery_target ON peg_time_deliveries(service,account,target_entry_id);
CREATE TABLE peg_time_delivery_history (
 id INTEGER PRIMARY KEY AUTOINCREMENT,service TEXT NOT NULL,account TEXT NOT NULL,entry_id TEXT NOT NULL,sheet_id TEXT NOT NULL,
 actor_id TEXT NOT NULL,at INTEGER NOT NULL,state TEXT NOT NULL,provider_id INTEGER,provider_seconds REAL,status_code INTEGER,reason TEXT
);
CREATE TRIGGER peg_time_delivery_acknowledged BEFORE UPDATE ON peg_time_deliveries WHEN OLD.state='acknowledged'
BEGIN SELECT RAISE(ABORT,'time_delivery_acknowledged'); END;
CREATE TRIGGER peg_time_delivery_kept BEFORE DELETE ON peg_time_deliveries BEGIN SELECT RAISE(ABORT,'time_delivery_history_is_preserved'); END;
CREATE TRIGGER peg_time_delivery_history_kept BEFORE UPDATE ON peg_time_delivery_history BEGIN SELECT RAISE(ABORT,'time_delivery_history_is_preserved'); END;
CREATE TRIGGER peg_time_delivery_history_undeleted BEFORE DELETE ON peg_time_delivery_history BEGIN SELECT RAISE(ABORT,'time_delivery_history_is_preserved'); END;

-- Add a permanent audit alongside the pre-existing access activity. No historical activity is rewritten.
CREATE TABLE peg_permanent_audit (
 id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id TEXT,at INTEGER NOT NULL,actor_id TEXT,action TEXT NOT NULL,
 target_type TEXT,target_id TEXT,subject_id TEXT,result TEXT NOT NULL DEFAULT 'success',detail TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX peg_permanent_audit_workspace ON peg_permanent_audit(workspace_id,id);
-- Historical rows are preserved as redacted permanent records, with no free-form metadata.
INSERT INTO peg_permanent_audit(workspace_id,at,actor_id,action,target_type,target_id,subject_id)
 SELECT workspace_id,at,actor_id,action,target_type,target_id,subject_id FROM peg_audit ORDER BY id;
CREATE TRIGGER peg_audit_permanent AFTER INSERT ON peg_audit WHEN COALESCE((SELECT applying FROM rer_portability_state WHERE id=1),0)=0 BEGIN
 INSERT INTO peg_permanent_audit(workspace_id,at,actor_id,action,target_type,target_id,subject_id,detail)
 VALUES(NEW.workspace_id,NEW.at,NEW.actor_id,NEW.action,NEW.target_type,NEW.target_id,NEW.subject_id,'{}');
END;
CREATE TRIGGER peg_permanent_audit_no_update BEFORE UPDATE ON peg_permanent_audit BEGIN SELECT RAISE(ABORT,'audit_append_only'); END;
CREATE TRIGGER peg_permanent_audit_no_delete BEFORE DELETE ON peg_permanent_audit BEGIN SELECT RAISE(ABORT,'audit_append_only'); END;
CREATE TRIGGER peg_history_audit AFTER INSERT ON peg_history WHEN COALESCE((SELECT applying FROM rer_portability_state WHERE id=1),0)=0 BEGIN
 INSERT INTO peg_permanent_audit(workspace_id,at,actor_id,action,target_type,target_id)
 SELECT CASE WHEN EXISTS(SELECT 1 FROM peg_task_projects WHERE task_id=NEW.task_id) THEN t.workspace_id ELSE NULL END,
 NEW.at,NEW.actor_id,'task.'||NEW.kind,'task',NEW.task_id FROM peg_tasks t WHERE t.id=NEW.task_id;
END;
CREATE TRIGGER peg_signin_audit AFTER INSERT ON oa_sessions BEGIN
 INSERT INTO peg_permanent_audit(workspace_id,at,actor_id,action,target_type,target_id)
 VALUES(NULL,NEW.created_at,NEW.operator_id,'authentication.signed_in','person',NEW.operator_id);
END;
CREATE TRIGGER peg_auth_change_audit AFTER INSERT ON oa_auth_audit BEGIN
 INSERT INTO peg_permanent_audit(workspace_id,at,actor_id,action,target_type,target_id)
 VALUES(NULL,NEW.created_at,NEW.actor_id,'authentication.configuration_changed','person',NEW.actor_id);
END;
